//! `TweenCollection` helpers and lifecycle against the pinned CesiumJS traces
//! in `tests/data/scene-tween-helpers.json` (generated by
//! `tools/cesium/generate-scene-tween-helpers.mjs`).

use cesium_rs::core::*;
use cesium_rs::scene::tween_collection::{Tween, TweenCallback};
use cesium_rs::scene::*;
use serde_json::{json, Value};
use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-tween-helpers.json")).unwrap()
}

fn assert_close(actual: f64, expected: &Value, context: &str) {
    let expected = expected.as_f64().unwrap();
    assert!((actual - expected).abs() <= 1e-12 * expected.abs().max(1.0), "{context}: {actual} != {expected}");
}

fn alpha(material: &Rc<RefCell<Material>>, name: &str) -> f64 {
    match material.borrow().uniform(name) {
        Some(MaterialValue::Vec4(c)) => c.w,
        other => panic!("{name} is not a color: {other:?}"),
    }
}

fn offset(material: &Rc<RefCell<Material>>) -> f64 {
    match material.borrow().uniform("offset") {
        Some(MaterialValue::Float(v)) => *v,
        other => panic!("offset is not a float: {other:?}"),
    }
}

type Log = Rc<RefCell<Vec<Value>>>;

fn event(log: &Log, entry: Value) -> TweenCallback {
    let log = log.clone();
    Rc::new(move || log.borrow_mut().push(entry.clone()))
}

#[test]
fn add_property_matches_reference() {
    let fixture = fixture();
    let collection = TweenCollection::new();
    let object = Rc::new(RefCell::new(BTreeMap::from([("x".to_string(), 5.0), ("other".to_string(), 1.0)])));
    let events: Log = Rc::default();
    collection
        .add_property(
            object.clone(),
            "x",
            0.0,
            10.0,
            TweenOptions {
                duration: 2.0,
                delay: 0.5,
                easing_function: TweenEasing::Builtin(EasingFunction::QuadraticInOut),
                complete: Some(event(&events, json!("complete"))),
                cancel: Some(event(&events, json!("cancel"))),
                ..Default::default()
            },
        )
        .unwrap();
    for step in fixture["property"].as_array().unwrap() {
        collection.update(step["time"].as_f64().unwrap());
        let context = format!("time {}", step["time"]);
        assert_close(object.borrow()["x"], &step["x"], &context);
        assert_close(object.borrow()["other"], &step["other"], &context);
        assert_eq!(json!(collection.length()), step["length"], "{context}");
        assert_eq!(json!(*events.borrow()), step["events"], "{context}");
    }
}

#[test]
fn add_alpha_matches_reference() {
    let fixture = fixture();
    let collection = TweenCollection::new();
    let stripe = Rc::new(RefCell::new(Material::from_type("Stripe")));
    let color = Rc::new(RefCell::new(Material::from_type("Color")));
    collection
        .add_alpha(
            stripe.clone(),
            0.2,
            0.8,
            TweenOptions {
                duration: 1.0,
                easing_function: TweenEasing::Builtin(EasingFunction::CubicOut),
                ..Default::default()
            },
        )
        .unwrap();
    // Cesium's defaults: fade in from 0 to 1 over 3 seconds.
    collection.add_alpha(color.clone(), 0.0, 1.0, TweenOptions::default()).unwrap();
    for step in fixture["alpha"].as_array().unwrap() {
        collection.update(step["time"].as_f64().unwrap());
        let context = format!("time {}", step["time"]);
        assert_close(alpha(&stripe, "evenColor"), &step["even"], &context);
        assert_close(alpha(&stripe, "oddColor"), &step["odd"], &context);
        assert_close(alpha(&color, "color"), &step["color"], &context);
        assert_eq!(json!(collection.length()), step["length"], "{context}");
    }
}

#[test]
fn add_offset_increment_matches_reference() {
    let fixture = fixture();
    let collection = TweenCollection::new();
    let stripe = Rc::new(RefCell::new(Material::from_type("Stripe")));
    stripe.borrow_mut().set_uniform("offset", MaterialValue::Float(0.25)).unwrap();
    let events: Log = Rc::default();
    let update_log = events.clone();
    collection
        .add_offset_increment(
            stripe.clone(),
            TweenOptions {
                duration: 1.0,
                delay: 0.25,
                // Cesium passes this to addProperty, which ignores it.
                update: Some(Rc::new(move |_| update_log.borrow_mut().push(json!("update")))),
                cancel: Some(event(&events, json!("cancel"))),
                ..Default::default()
            },
        )
        .unwrap();
    for step in fixture["offset"].as_array().unwrap() {
        match step["time"].as_f64() {
            Some(time) => collection.update(time),
            None => collection.remove_all(),
        }
        let context = format!("time {}", step["time"]);
        assert_close(offset(&stripe), &step["offset"], &context);
        assert_eq!(json!(collection.length()), step["length"], "{context}");
        assert_eq!(json!(*events.borrow()), step["events"], "{context}");
    }
}

#[test]
fn lifecycle_matches_reference() {
    let fixture = fixture();
    let collection = TweenCollection::new();
    let log: Log = Rc::default();
    let make = |name: &str, duration: f64| {
        let update_log = log.clone();
        let update_name = name.to_string();
        collection
            .add(TweenOptions {
                start_object: BTreeMap::from([("v".to_string(), 0.0)]),
                stop_object: BTreeMap::from([("v".to_string(), 1.0)]),
                duration,
                update: Some(Rc::new(move |value| {
                    let v = value["v"];
                    // JSON numbers as Cesium writes them: whole values without a fraction.
                    let v = if v.fract() == 0.0 { json!(v as i64) } else { json!(v) };
                    update_log.borrow_mut().push(json!([update_name, "update", v]));
                })),
                complete: Some(event(&log, json!([name, "complete"]))),
                cancel: Some(event(&log, json!([name, "cancel"]))),
                ..Default::default()
            })
            .unwrap()
    };
    let mut steps = fixture["lifecycle"].as_array().unwrap().iter();
    let mut check = |op: &str, result: Option<Value>| {
        let step = steps.next().unwrap();
        assert_eq!(step["op"], op);
        if let Some(result) = result {
            assert_eq!(result, step["result"], "{op} result");
        }
        assert_eq!(json!(collection.length()), step["length"], "{op} length");
        let entries: Vec<Value> = log.borrow_mut().drain(..).collect();
        assert_eq!(json!(entries), step["log"], "{op} log");
    };

    let a = make("a", 1.0);
    let b = make("b", 2.0);
    let c = make("c", 3.0);
    check("add three", Some(Value::Null));
    let zero = make("zero", 0.0);
    check("add zero", Some(json!({"contains": collection.contains(&zero), "hasCollectionTween": false})));
    let named = |t: Option<Tween>| -> Value {
        match t {
            Some(t) if collection.contains(&t) && collection.get(0).is_some() => {
                for (name, candidate) in [("a", &a), ("b", &b), ("c", &c)] {
                    if t.ptr_eq(candidate) {
                        return json!(name);
                    }
                }
                Value::Null
            }
            _ => Value::Null,
        }
    };
    check("get", Some(json!((0..4).map(|i| named(collection.get(i))).collect::<Vec<_>>())));
    collection.update(0.0);
    check("update 0", Some(Value::Null));
    collection.update(0.5);
    check("update 0.5", Some(Value::Null));
    check("remove b", Some(json!(collection.remove(&b))));
    check("remove b again", Some(json!(collection.remove(&b))));
    check(
        "contains",
        Some(json!({"a": collection.contains(&a), "b": collection.contains(&b), "c": collection.contains(&c)})),
    );
    // Cesium's cancelTween returns undefined.
    c.cancel_tween();
    check("cancelTween c", None);
    collection.update(1.0);
    check("update 1", Some(Value::Null));
    let d = make("d", 1.0);
    let e = make("e", 1.0);
    check("add d e", Some(Value::Null));
    collection.remove_all();
    check("removeAll", Some(json!({"d": collection.contains(&d), "e": collection.contains(&e)})));
    collection.update(2.0);
    check("update 2", Some(Value::Null));
}

#[test]
fn helper_errors_match_reference() {
    let fixture = fixture();
    let errors: BTreeMap<String, String> = fixture["errors"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| (e["name"].as_str().unwrap().into(), e["error"].as_str().unwrap().into()))
        .collect();
    let collection = TweenCollection::new();
    let message = |r: Result<Tween, RuntimeError>| r.err().expect("an error").message;
    assert_eq!(
        message(collection.add(TweenOptions { duration: -1.0, ..Default::default() })),
        errors["negative duration"]
    );
    let object = Rc::new(RefCell::new(BTreeMap::from([("x".to_string(), 1.0)])));
    assert_eq!(
        message(collection.add_property(object, "y", 0.0, 1.0, TweenOptions::default())),
        errors["missing property"]
    );
    let plain = Rc::new(RefCell::new(Material::new(MaterialOptions {
        fabric: Fabric::default()
            .uniform("u", MaterialValue::Float(1.0))
            .source("czm_material czm_getMaterial(czm_materialInput m) { return czm_getDefaultMaterial(m); }"),
        ..Default::default()
    })));
    assert_eq!(message(collection.add_alpha(plain, 0.0, 1.0, TweenOptions::default())), errors["no alpha uniforms"]);
    let color = Rc::new(RefCell::new(Material::from_type("Color")));
    assert_eq!(message(collection.add_offset_increment(color, TweenOptions::default())), errors["no offset uniform"]);
}
